 @Override public void onCreate(Bundle b){super.onCreate(b);auth=FirebaseAuth.getInstance();db=FirebaseFirestore.getInstance();storage=FirebaseStorage.getInstance();if(auth.getCurrentUser()==null)login();else boot();}
 void login(){LinearLayout r=base();r.setGravity(Gravity.CENTER);r.setPadding(dp(24),dp(20),dp(24),dp(20));ImageView logo=new ImageView(this);logo.setImageResource(com.gigbiz.app.R.drawable.ic_gigbiz);logo.setScaleType(ImageView.ScaleType.FIT_CENTER);r.addView(logo,new LinearLayout.LayoutParams(dp(100),dp(100)));TextView h=tv("GigSathi",32,true);h.setGravity(Gravity.CENTER);r.addView(h,new LinearLayout.LayoutParams(-1,dp(60)));TextView s=tv("Earn • Work • Grow",17,false);s.setGravity(Gravity.CENTER);r.addView(s,new LinearLayout.LayoutParams(-1,dp(40)));EditText e=field("Email"),p=field("Password");p.setInputType(0x81);add(r,e,54,10);add(r,p,54,10);TextView b=button("LOGIN",purple);add(r,b,54,18);TextView n=tv("New worker? Create account",15,true);n.setGravity(Gravity.CENTER);add(r,n,45,8);TextView m=tv("Team Member Login / Register",15,true);m.setTextColor(purple);m.setGravity(Gravity.CENTER);add(r,m,48,4);b.setOnClickListener(v->{auth.signInWithEmailAndPassword(e.getText().toString().trim(),p.getText().toString()).addOnCompleteListener(x->{if(x.isSuccessful())boot();else toast(err(x.getException()));});});n.setOnClickListener(v->signup());m.setOnClickListener(v->memberAuthScreen(false));setContentView(r);}
 EditText field(String h){EditText e=new EditText(this);e.setHint(h);e.setSingleLine(true);e.setTextSize(15);e.setPadding(dp(14),0,dp(14),0);e.setBackground(stroke(Color.rgb(220,225,232),1,11));return e;}
 void signup(){LinearLayout r=base();r.setPadding(dp(22),dp(28),dp(22),dp(20));TextView h=tv("Create your GigSathi account",26,true);h.setGravity(Gravity.CENTER);add(r,h,65,0);EditText n=field("Full name"),e=field("Email"),ph=field("Mobile number"),sk=field("Skills"),loc=field("City / Location"),pw=field("Password (6+)");pw.setInputType(0x81);for(EditText x:new EditText[]{n,e,ph,sk,loc,pw})add(r,x,53,8);TextView b=button("CREATE ACCOUNT",purple);add(r,b,53,18);b.setOnClickListener(v->{auth.createUserWithEmailAndPassword(e.getText().toString().trim(),pw.getText().toString()).addOnCompleteListener(x->{if(!x.isSuccessful()){toast(err(x.getException()));return;}Map<String,Object> m=new HashMap<>();m.put("name",n.getText().toString().trim());m.put("email",e.getText().toString().trim());m.put("phone",ph.getText().toString().trim());m.put("skills",sk.getText().toString().trim());m.put("location",loc.getText().toString().trim());m.put("role","worker");m.put("wallet",0);m.put("status","active");m.put("createdAt",FieldValue.serverTimestamp());db.collection("users").document(auth.getCurrentUser().getUid()).set(m).addOnSuccessListener(z->boot()).addOnFailureListener(q->toast(err(q)));});});setContentView(r);}
 
