  LinearLayout banner=new LinearLayout(this);banner.setOrientation(1);banner.setPadding(dp(18),dp(14),dp(14),dp(12));banner.setBackground(bg(Color.rgb(15,57,112),16));TextView tag=tv("GIGSATHI • WORK & EARN",12,true);tag.setTextColor(Color.rgb(255,202,54));banner.addView(tag);TextView title=tv("Earn more with\nGigSathi Projects",25,true);title.setTextColor(white);add(banner,title,-2,5);TextView sub=tv("Discover projects • Refer customers • Get rewarded",12,false);sub.setTextColor(Color.rgb(238,244,255));banner.addView(sub);TextView go=button("EXPLORE PROJECTS  →",Color.rgb(230,35,57));add(banner,go,42,8);go.setOnClickListener(v->gigsScreen());LinearLayout.LayoutParams bp=new LinearLayout.LayoutParams(-1,dp(190));bp.setMargins(0,dp(8),0,dp(16));c.addView(banner,bp);
  TextView offerHeading=tv("OFFERS FOR YOU",18,true);offerHeading.setPadding(dp(2),dp(14),0,dp(5));c.addView(offerHeading);HorizontalScrollView offerScroll=new HorizontalScrollView(this);offerScroll.setHorizontalScrollBarEnabled(false);LinearLayout offerRow=new LinearLayout(this);offerRow.setOrientation(0);offerScroll.addView(offerRow);c.addView(offerScroll,new LinearLayout.LayoutParams(-1,dp(112)));db.collection("offers").whereEqualTo("status","active").get().addOnSuccessListener(offers->{offerRow.removeAllViews();for(DocumentSnapshot od:offers){LinearLayout oc=new LinearLayout(this);oc.setOrientation(1);oc.setPadding(dp(12),dp(8),dp(12),dp(8));oc.setBackground(stroke(Color.rgb(220,232,255),1,14));oc.addView(tv(od.getString("title")==null?"Special Offer":od.getString("title"),15,true));oc.addView(tv(od.getString("description")==null?"Tap to learn more":od.getString("description"),12,false));LinearLayout.LayoutParams op=new LinearLayout.LayoutParams(dp(235),dp(96));op.setMargins(0,dp(3),dp(8),dp(4));offerRow.addView(oc,op);String link=od.getString("linkUrl");oc.setOnClickListener(v->{if(link!=null&&!link.isEmpty())try{startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(link)));}catch(Exception ex){toast("Invalid offer link.");}});}if(offers.isEmpty())offerRow.addView(tv("New offers will appear here.",13,false));}).addOnFailureListener(e->toast("Offers unavailable: "+err(e)));
  LinearLayout money=new LinearLayout(this);View pending=moneyCard("Pending","₹ "+String.format(Locale.US,"%.2f",numberVal(u.get("pendingEarnings"))),Color.rgb(250,235,229),Color.rgb(54,128,220),"⌛");LinearLayout.LayoutParams a=new LinearLayout.LayoutParams(0,dp(82),1);a.setMargins(0,0,dp(5),0);money.addView(pending,a);pending.setOnClickListener(v->leadsScreen());View paid=moneyCard("Paid","₹ "+String.format(Locale.US,"%.2f",numberVal(u.get("paidEarnings"))),Color.rgb(226,249,222),Color.rgb(36,150,70),"✓");LinearLayout.LayoutParams b=new LinearLayout.LayoutParams(0,dp(82),1);b.setMargins(dp(5),0,0,0);money.addView(paid,b);paid.setOnClickListener(v->withdrawScreen());c.addView(money); final TextView pendingValue=(TextView)((LinearLayout)pending).getChildAt(1); final TextView paidValue=(TextView)((LinearLayout)paid).getChildAt(1); db.collection("leads").whereEqualTo("workerId",auth.getCurrentUser().getUid()).get().addOnSuccessListener(ls->{double pend=0,credited=0;for(DocumentSnapshot ld:ls){double amount=numberVal(ld.get("taskAmount"));boolean isPaid=Boolean.TRUE.equals(ld.getBoolean("walletCredited")) || "complete".equalsIgnoreCase(ld.getString("status"));if(isPaid)credited+=amount;else if(!"reject".equalsIgnoreCase(ld.getString("status")) && !"rejected".equalsIgnoreCase(ld.getString("status")))pend+=amount;}pendingValue.setText("₹ "+String.format(Locale.US,"%.2f",pend));paidValue.setText("₹ "+String.format(Locale.US,"%.2f",credited));}).addOnFailureListener(e->toast("Earnings could not refresh: "+err(e)));
