 String normalizedCategoryValue(Object value){return value==null?"":String.valueOf(value).trim().replaceAll("\\s+"," ").toLowerCase(Locale.ROOT);}
  boolean categoryMatches(DocumentSnapshot d,String categoryId,String categoryName){
   String selectedId=normalizedCategoryValue(categoryId), selectedName=normalizedCategoryValue(categoryName);
   for(String key:new String[]{"categoryId","category_id","selectedCategoryId","selectedCategory","categoryRef","categoryDocId"}){Object value=d.get(key);if(value instanceof DocumentReference)value=((DocumentReference)value).getId();String candidate=normalizedCategoryValue(value);if(!selectedId.isEmpty()&&selectedId.equals(candidate))return true;}
   for(String key:new String[]{"categoryName","category","categoryTitle","category_name"}){Object value=d.get(key);if(value instanceof Map){Map<?,?> map=(Map<?,?>)value;value=map.containsKey("name")?map.get("name"):map.get("id");}String candidate=normalizedCategoryValue(value);if(!selectedName.isEmpty()&&selectedName.equals(candidate))return true;if(!selectedId.isEmpty()&&selectedId.equals(candidate))return true;}
   return false;
  }
