  boolean emValid(String em){return em!=null&&em.matches("^[A-Za-z0-9+_.-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$");}
  void addTeamMemberForm(String ownerId){
   LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(dp(6),dp(4),dp(6),dp(4));
   EditText name=field("Member full name"),phone=field("Mobile number"),email=field("Member email (required for login)"),role=field("Role (e.g. Member / Team Leader)");
   for(EditText e:new EditText[]{name,phone,email,role})add(box,e,52,7);
   new AlertDialog.Builder(this).setTitle("Add Team Member").setView(box).setNegativeButton("Cancel",null).setPositiveButton("Save Member",(dialog,which)->{
    String n=name.getText().toString().trim(),ph=phone.getText().toString().trim(),em=email.getText().toString().trim().toLowerCase(Locale.ROOT),rl=role.getText().toString().trim();
    if(n.length()<2||ph.replaceAll("\\D","").length()<10||!emValid(em)){toast("Enter member name, valid mobile and member email.");return;}
    Map<String,Object> data=new HashMap<>();data.put("ownerId",ownerId);data.put("name",n);data.put("phone",ph);data.put("email",em);data.put("memberRole",rl.isEmpty()?"Member":rl);data.put("status","invited");data.put("createdAt",FieldValue.serverTimestamp());
    db.collection("teamMembers").add(data).addOnSuccessListener(x->{toast("Team member added.");teamScreen();}).addOnFailureListener(e->toast("Could not add member: "+err(e)));
   }).show();
  }

