 String pinHash(String salt,String pin){try{java.security.MessageDigest md=java.security.MessageDigest.getInstance("SHA-256");byte[] b=(salt+":"+pin).getBytes("UTF-8");byte[] h=md.digest(b);StringBuilder out=new StringBuilder();for(byte x:h)out.append(String.format(Locale.US,"%02x",x));return out.toString();}catch(Exception e){return "";}}
 void withdrawalPinScreen(){android.content.SharedPreferences p=getSharedPreferences("gigbiz_secure",MODE_PRIVATE);String salt=p.getString("withdrawPinSalt","");LinearLayout box=base();box.setPadding(dp(16),dp(12),dp(16),dp(12));EditText pin=field(salt.isEmpty()?"Create 6 digit withdrawal PIN":"New 6 digit withdrawal PIN");pin.setInputType(2);pin.setTransformationMethod(android.text.method.PasswordTransformationMethod.getInstance());EditText confirm=field("Confirm PIN");confirm.setInputType(2);confirm.setTransformationMethod(android.text.method.PasswordTransformationMethod.getInstance());add(box,pin,54,8);add(box,confirm,54,8);new AlertDialog.Builder(this).setTitle(salt.isEmpty()?"Set Withdrawal PIN":"Change Withdrawal PIN").setMessage("PIN is stored securely in your account so it remains after reinstall. Contact Admin if you forget it.").setView(box).setPositiveButton("SAVE",(di,w)->{String v=pin.getText().toString().trim(),c=confirm.getText().toString().trim();if(!v.matches("\\d{6}")||!v.equals(c)){toast("PIN must be 6 digits and both entries must match.");return;}String ns=UUID.randomUUID().toString(),hash=pinHash(ns,v);String uid=auth.getCurrentUser().getUid();Map<String,Object> update=new HashMap<>();update.put("withdrawPinSalt",ns);update.put("withdrawPinHash",hash);update.put("withdrawPinUpdatedAt",FieldValue.serverTimestamp());db.collection("users").document(uid).update(update).addOnSuccessListener(a->{p.edit().putString("withdrawPinSalt",ns).putString("withdrawPinHash",hash).apply();toast("Wallet PIN saved to your account. It will remain after reinstall.");boot();}).addOnFailureListener(e->toast("PIN save failed. Please try again: "+err(e)));}).setNegativeButton("CANCEL",null).show();}
 void withdrawScreen(){
  String uid=auth.getCurrentUser().getUid();
  db.collection("users").document(uid).get().addOnSuccessListener(userDoc->{
   String cloudSalt=userDoc.getString("withdrawPinSalt"),cloudHash=userDoc.getString("withdrawPinHash");
   android.content.SharedPreferences local=getSharedPreferences("gigbiz_secure",MODE_PRIVATE);
   if(cloudHash==null||cloudHash.isEmpty()){
    new AlertDialog.Builder(this).setTitle("Set Wallet PIN").setMessage("Set a 6-digit Wallet PIN. It will be saved to your account and remain after reinstall. If forgotten, contact Admin.").setNegativeButton("CANCEL",null).setPositiveButton("SET WALLET PIN",(d,w)->withdrawalPinScreen()).show();return;
   }
   EditText pinInput=field("Enter 6 digit Wallet PIN");pinInput.setInputType(2);pinInput.setTransformationMethod(android.text.method.PasswordTransformationMethod.getInstance());
   new AlertDialog.Builder(this).setTitle("Verify Wallet PIN").setMessage("Forgot PIN? Contact Admin for account verification and reset.").setView(pinInput).setNegativeButton("CANCEL",null).setNeutralButton("CONTACT ADMIN",(d,w)->{new AlertDialog.Builder(this).setTitle("Contact Admin").setMessage("Please contact Great India Technology Admin and provide your registered login email and UID. Admin should verify your identity before resetting the Wallet PIN.").setPositiveButton("OK",null).show();}).setPositiveButton("CONTINUE",(d,w)->{
    String entered=pinInput.getText().toString().trim();
    if(!entered.matches("\\d{6}")||!pinHash(cloudSalt==null?"":cloudSalt,entered).equals(cloudHash)){toast("Incorrect Wallet PIN. If forgotten, contact Admin.");return;}
    local.edit().putString("withdrawPinSalt",cloudSalt==null?"":cloudSalt).putString("withdrawPinHash",cloudHash).apply();
    withdrawalDetailsScreen();
   }).show();
  }).addOnFailureListener(e->toast("Could not load Wallet PIN. Check internet and try again: "+err(e)));
 }
