 void loadAdviserPhoto(ImageView target,DocumentSnapshot user){
  String uid=user.getId();
  String local=getSharedPreferences("gigbiz_worker_photos",MODE_PRIVATE).getString(uid,"");
  if(local!=null&&!local.isEmpty()){try{target.setImageURI(Uri.parse(local));if(target.getDrawable()!=null)return;}catch(Exception ignored){}}
  String url=user.getString("workerPhotoUrl");
  if(url!=null&&!url.trim().isEmpty()){
   try{storage.getReferenceFromUrl(url).getBytes(2*1024*1024).addOnSuccessListener(bytes->{try{Bitmap bitmap=BitmapFactory.decodeByteArray(bytes,0,bytes.length);if(bitmap!=null)target.setImageBitmap(bitmap);else target.setImageResource(com.gigbiz.app.R.drawable.ic_gigbiz);}catch(Exception e){target.setImageResource(com.gigbiz.app.R.drawable.ic_gigbiz);}}).addOnFailureListener(e->target.setImageResource(com.gigbiz.app.R.drawable.ic_gigbiz));return;}catch(Exception ignored){}
  }
  target.setImageResource(com.gigbiz.app.R.drawable.ic_gigbiz);
 }
