 @Override protected void onActivityResult(int requestCode,int resultCode,Intent data){
  super.onActivityResult(requestCode,resultCode,data);if(resultCode!=RESULT_OK||data==null||data.getData()==null)return;Uri uri=data.getData();
  if(requestCode==PICK_WORKER_PHOTO){String uid=auth.getCurrentUser()==null?"":auth.getCurrentUser().getUid();if(uid.isEmpty())return;try{getContentResolver().takePersistableUriPermission(uri,Intent.FLAG_GRANT_READ_URI_PERMISSION);}catch(Exception ignored){}getSharedPreferences("gigbiz_worker_photos",MODE_PRIVATE).edit().putString(uid,uri.toString()).apply();if(workerPhotoView!=null)workerPhotoView.setImageURI(uri);storage.getReference().child("worker-photos/"+uid+"/id-photo.jpg").putFile(uri).addOnSuccessListener(t->t.getStorage().getDownloadUrl().addOnSuccessListener(url->db.collection("users").document(uid).update("workerPhotoUrl",url.toString()).addOnSuccessListener(v->toast("Adviser photo uploaded.")).addOnFailureListener(e->toast("Photo saved, profile update failed: "+err(e))))).addOnFailureListener(e->toast("Photo selected on device, cloud upload failed: "+err(e)));return;}
  if(requestCode==714||requestCode==715){boolean idCard=requestCode==715;String content=idCard?idPdfText:offerPdfText;try{
   PdfDocument pdf=new PdfDocument();Paint p=new Paint(3);int pageW=idCard?420:595,pageH=idCard?660:842;
   PdfDocument.Page page=pdf.startPage(new PdfDocument.PageInfo.Builder(pageW,pageH,1).create());Canvas canvas=page.getCanvas();
   int navy=Color.rgb(8,42,91),orange=Color.rgb(245,126,32);canvas.drawColor(Color.WHITE);p.setColor(navy);canvas.drawRect(0,0,pageW,idCard?115:105,p);
   p.setColor(orange);canvas.drawRect(0,idCard?110:100,pageW,idCard?116:106,p);
   p.setColor(Color.WHITE);p.setTypeface(Typeface.DEFAULT_BOLD);p.setTextSize(idCard?26:23);canvas.drawText("GigSathi",32,42,p);
   p.setTypeface(Typeface.DEFAULT);p.setTextSize(9);canvas.drawText("TOGETHER FOR A BETTER TOMORROW",32,63,p);
   p.setColor(navy);p.setTypeface(Typeface.DEFAULT_BOLD);p.setTextSize(idCard?15:18);canvas.drawText(idCard?"ADVISER ID CARD":"ADVISER OFFER LETTER — DRAFT",32,idCard?145:137,p);
   p.setColor(Color.DKGRAY);p.setTypeface(Typeface.DEFAULT);p.setTextSize(idCard?11:10);int y=idCard?177:166;int left=32,maxChars=idCard?43:83,lineHeight=idCard?25:17;
   for(String paragraph:content.split("\\n")){String remaining=paragraph;if(remaining.isEmpty()){y+=lineHeight/2;continue;}while(remaining.length()>maxChars){int cut=remaining.lastIndexOf(' ',maxChars);if(cut<1)cut=maxChars;canvas.drawText(remaining.substring(0,cut),left,y,p);remaining=remaining.substring(cut).trim();y+=lineHeight;if(y>pageH-55)break;}if(y<=pageH-55){canvas.drawText(remaining,left,y,p);y+=lineHeight;}if(y>pageH-55)break;}
   p.setColor(orange);canvas.drawRect(0,pageH-42,pageW, pageH,p);p.setColor(Color.WHITE);p.setTypeface(Typeface.DEFAULT_BOLD);p.setTextSize(9);canvas.drawText(idCard?"DIGITAL PROFILE ID • NOT A GOVERNMENT ID":"DRAFT ONLY • REVIEW AND AUTHORIZE BEFORE ISSUE",32,pageH-17,p);
   pdf.finishPage(page);OutputStream out=getContentResolver().openOutputStream(uri);if(out==null)throw new java.io.IOException("Cannot save PDF");pdf.writeTo(out);out.close();pdf.close();toast(idCard?"Adviser ID Card PDF saved.":"Offer Letter PDF saved.");
  }catch(Exception e){toast("PDF error: "+e.getMessage());}}
 }
 String idPdfText="";
 String offerPdfText="";
 void workerOfferLetter(DocumentSnapshot u){
  String name=u.getString("name");if(name==null||name.trim().isEmpty())name="Adviser";
  String email=auth.getCurrentUser().getEmail();if(email==null)email="";
  String phone=u.getString("phone");if(phone==null)phone="Not provided";
  String date=java.text.DateFormat.getDateInstance(java.text.DateFormat.MEDIUM,java.util.Locale.getDefault()).format(new java.util.Date());
  String letter="GREAT INDIA TECHNOLOGY™ / GIGSATHI\nADVISER OFFER LETTER — DRAFT\nDate: "+date+"\n\nTo: "+name+"\nEmail: "+email+"\nMobile: "+phone+"\n\nDear "+name+",\n\nWe invite you to register your interest in performing eligible tasks and projects through the GigSathi platform. Work availability, task instructions, eligibility, verification and any payment are subject to the applicable task terms and review by the platform administrator.\n\nRole: Independent platform adviser / task participant\nWork type: Task- or project-based, as offered in the app\nPayment: Only the amount shown for a task that is completed and approved under its stated terms\n\nThis document is a draft template for review. It is not proof of employment, a guarantee of work, or a guarantee of income. It becomes an official offer only if separately reviewed and signed by an authorized representative with the final terms.\n\nRegards,\nLavkush R\nGreat India Technology™";
  LinearLayout root=base();topBar(root,"Offer Letter");
  ScrollView scroll=new ScrollView(this);LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(dp(18),dp(18),dp(18),dp(18));box.setBackground(bg(white,12));
  TextView h=tv("GREAT INDIA TECHNOLOGY™",18,true);h.setTextColor(Color.rgb(8,42,91));box.addView(h);
  TextView sub=tv("ADVISER OFFER LETTER — DRAFT",14,true);sub.setTextColor(muted);add(box,sub,38,4);
  TextView body=tv(letter.substring(letter.indexOf("Date:")),14,false);body.setPadding(dp(4),dp(12),dp(4),dp(12));box.addView(body);
  scroll.addView(box);LinearLayout.LayoutParams bp=new LinearLayout.LayoutParams(-1,-2);bp.setMargins(dp(14),dp(14),dp(14),dp(8));root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));
  TextView note=tv("Draft only — review and authorize before issuing as an official offer.",12,false);note.setTextColor(muted);note.setPadding(dp(16),dp(6),dp(16),dp(6));root.addView(note);
  TextView pdf=button("DOWNLOAD OFFER LETTER PDF",Color.rgb(8,42,91));add(root,pdf,52,8);pdf.setOnClickListener(v->{offerPdfText=letter;Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("application/pdf");i.putExtra(Intent.EXTRA_TITLE,"GigSathi_Adviser_Offer_Letter_DRAFT.pdf");startActivityForResult(i,714);});
  TextView share=button("SHARE OFFER LETTER DRAFT",green);add(root,share,52,8);share.setOnClickListener(v->shareDocument("GigSathi Adviser Offer Letter Draft",letter));
  setContentView(root);
 }
 void shareDocument(String title,String body){
  Intent i=new Intent(Intent.ACTION_SEND);i.setType("text/plain");i.putExtra(Intent.EXTRA_SUBJECT,title);i.putExtra(Intent.EXTRA_TEXT,body);startActivity(Intent.createChooser(i,"Share "+title));
 }
 void showInfo(String title,String message){new AlertDialog.Builder(this).setTitle(title).setMessage(message).setPositiveButton("OK",null).show();}
 void deleteAccountConfirm(DocumentSnapshot u){
  new AlertDialog.Builder(this).setTitle("Delete Account?").setMessage("Your GigSathi profile and account will be permanently deleted. This cannot be undone. Continue?").setNegativeButton("CANCEL",null).setPositiveButton("DELETE",(d,w)->{
   String uid=auth.getCurrentUser().getUid();db.collection("users").document(uid).delete().addOnCompleteListener(x->{auth.getCurrentUser().delete().addOnCompleteListener(y->{if(y.isSuccessful()){getSharedPreferences("gigbiz_secure",MODE_PRIVATE).edit().clear().apply();toast("Account deleted.");login();}else toast("For security, please login again and retry account deletion.");});});
  }).show();
 }
 void topBar(LinearLayout r,String title){TextView b=tv("‹  "+title,20,true);b.setTextColor(purple);b.setPadding(dp(14),dp(15),0,dp(15));r.addView(b,new LinearLayout.LayoutParams(-1,dp(60)));b.setOnClickListener(v->{db.collection("users").document(auth.getCurrentUser().getUid()).get().addOnSuccessListener(this::home);});}
 String err(Exception e){return e==null?"Something went wrong":e.getMessage()==null?"Operation failed":e.getMessage();}
